confusao = {"0": "O", "1": "l", "5": "S", "8": "B", ",": "."}
def ocr_simulado(texto, p, rg):   # confusões programadas por nós
    return "".join(confusao[c] if (c in confusao and rg.random() < p)
                   else c for c in texto)
# CER = distância de Levenshtein / comprimento da referência
